def transform(grid):
    out=[row[:] for row in grid]
    # Color 4 marks background holes enclosed by the foreground outline.
    h,w=len(grid),len(grid[0])
    counts={}
    for row in grid:
        for x in row: counts[x]=counts.get(x,0)+1
    bg=max(counts,key=counts.get)
    fg=max((x for x in counts if x!=bg),key=lambda x:counts[x])
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==fg]
    r0=min(r for r,c in pts); r1=max(r for r,c in pts)
    c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    seen=set()
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if grid[r][c]!=bg or (r,c) in seen: continue
            stack=[(r,c)]; comp=[]; seen.add((r,c)); outside=False
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                if y in (r0,r1) or x in (c0,c1): outside=True
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if r0<=yy<=r1 and c0<=xx<=c1 and grid[yy][xx]==bg and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            if not outside:
                for y,x in comp: out[y][x]=4
    return out

